import math

class Turtle:
    """Stand-in for turtle.Turtle (no display): tracks heading, position and pen."""
    def __init__(self):
        self._x = 0.0
        self._y = 0.0
        self._h = 0.0
        self._down = True
    def left(self, d):
        self._h = (self._h + d) % 360
    def right(self, d):
        self._h = (self._h - d) % 360
    def setheading(self, d):
        self._h = float(d) % 360
    def forward(self, dist):
        self._x += dist * math.cos(math.radians(self._h))
        self._y += dist * math.sin(math.radians(self._h))
    def up(self):
        self._down = False
    def down(self):
        self._down = True
    def isdown(self):
        return self._down
    def heading(self):
        return float(self._h)

t = Turtle()
t.left(90)
t.forward(30)
t.left(90)
t.right(45)
print(t.heading())

