class Image:
    """Stand-in for the book's images.Image: a grid of RGB tuples."""
    def __init__(self, width, height):
        self._w = width
        self._h = height
        self._px = [[(0, 0, 0)] * width for _ in range(height)]
    def getWidth(self):
        return self._w
    def getHeight(self):
        return self._h
    def getPixel(self, x, y):
        return self._px[y][x]
    def setPixel(self, x, y, rgb):
        self._px[y][x] = rgb
    def clone(self):
        new = Image(self._w, self._h)
        new._px = [row[:] for row in self._px]
        return new

def blackAndWhite(image):
    blackPixel = (0, 0, 0)
    whitePixel = (255, 255, 255)
    for y in range(image.getHeight()):
        for x in range(image.getWidth()):
            (r, g, b) = image.getPixel(x, y)
            average = (r + g + b) // 3
            if average < 128:
                image.setPixel(x, y, blackPixel)
            else:
                image.setPixel(x, y, whitePixel)

image = Image(2, 1)
image.setPixel(0, 0, (90, 120, 160))
image.setPixel(1, 0, (250, 30, 120))
blackAndWhite(image)
print(image.getPixel(0, 0), image.getPixel(1, 0))
